bodies={
'jquery.html':'''<h1 class="page-title">Кино іздеу</h1><p>Атауын жазыңыз: нәтижелер, ұсыныстар және белгіленген сөздер бірден жаңарады.</p><label for="jqSearch" class="form-label">Кино атауы</label><input id="jqSearch" class="form-control" autocomplete="off" role="combobox" aria-expanded="false" aria-controls="jqSuggestions"><ul id="jqSuggestions" class="list-group" role="listbox" hidden></ul><p id="jqCount" role="status" class="mt-3"></p><div id="jqResults" class="row row-cols-1 row-cols-md-2 g-3"></div>''',
'jquery-ux.html':'''<h1 class="page-title">Кино клубының жаңалықтары</h1><p>Кино әлеміндегі таңдаулар мен жеке ұсыныстар.</p><section class="card mb-4"><div class="card-body d-flex gap-5 flex-wrap"><p><strong class="jq-counter fs-2" data-target="34">0</strong><br>Туынды</p><p><strong class="jq-counter fs-2" data-target="22">0</strong><br>Жанр</p><p><strong class="jq-counter fs-2" data-target="9">0</strong><br>Апталық таңдау</p></div></section><form id="jqForm" class="card p-4 mb-5"><h2 class="h4">Ұсыныс жіберу</h2><p>Оқу демосы: хабарлама серверге жіберілмейді.</p><label for="jqName">Атыңыз</label><input id="jqName" class="form-control mb-3" required minlength="2" maxlength="60"><label for="jqMessage">Қандай кино ұсынасыз?</label><textarea id="jqMessage" class="form-control mb-3" required maxlength="500"></textarea><button id="jqSubmit" type="submit" class="btn btn-danger">Жіберу</button><p id="jqFormStatus" class="mt-3" role="status"></p></form><div id="jqReading"></div>''',
'jquery-tools.html':'''<h1 class="page-title">Постерлер мен бөлісу</h1><section class="card p-4 mb-4"><h2 class="h5">Достарыңызбен бөлісіңіз</h2><p id="jqShare">67Films — кино кешіне жаңа идея: https://symbtmn.github.io/67films/</p><button id="jqCopy" type="button" class="btn btn-outline-danger align-self-start" aria-describedby="jqCopyTip">Көшіру</button><span id="jqCopyTip" class="mt-2" role="status" hidden>Көшірілді!</span><button id="jqNotify" type="button" class="btn btn-outline-secondary mt-3 align-self-start">Тізімге қосу</button></section><div id="jqLazyGrid" class="row row-cols-2 row-cols-md-3 g-4"></div>'''}
for file,body in bodies.items():
 g.page(p,file,'Кино клубы / jQuery',nav+body,True)
